function validate([prices, fee]) {
  if (!Array.isArray(prices) || prices.length < 1 || prices.length > 50000) return 'prices needs 1 to 5 * 10^4 values.';
  if (prices.some(p => !Number.isInteger(p) || p < 1 || p >= 50000)) return 'Each price is a whole number from 1 to 49999.';
  if (!Number.isInteger(fee) || fee < 0 || fee >= 50000) return 'fee is a whole number from 0 to 49999.';
  return null;
}

