function maxProfit(prices, fee) {
  let cash = 0;
  let hold = -prices[0];

  for (let i = 1; i < prices.length; i++) {
    const price = prices[i];
    const nextCash = Math.max(cash, hold + price - fee);
    const nextHold = Math.max(hold, cash - price);
    cash = nextCash;
    hold = nextHold;
  }
  return cash;
}

