function maxProfit(prices, fee) {
  // best[k]: largest profit using only days 0..k-1 and owning nothing afterwards.
  const n = prices.length;
  const best = new Array(n + 1).fill(0);
  for (let k = 0; k < n; k++) {
    best[k + 1] = best[k];
    for (let buy = 0; buy < k; buy++) {
      best[k + 1] = Math.max(best[k + 1], best[buy] + prices[k] - prices[buy] - fee);
    }
  }
  return best[n];
}

