function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 10);
  const top = large ? 49999 : (rand() < 0.15 ? 49999 : 12);
  const prices = [];
  if (rand() < 0.5) {
    for (let i = 0; i < n; i++) prices.push(1 + Math.floor(rand() * top));
  } else {
    // A random walk gives runs of rises and falls.
    const step = Math.max(1, Math.floor(top / (large ? 50 : 4)));
    let price = 1 + Math.floor(rand() * top);
    for (let i = 0; i < n; i++) {
      price += Math.floor(rand() * (2 * step + 1)) - step;
      price = Math.min(top, Math.max(1, price));
      prices.push(price);
    }
  }
  const r = rand();
  const fee = r < 0.2 ? 0 : r < 0.9 ? Math.floor(rand() * Math.max(2, top / 3)) : Math.floor(rand() * 50000);
  return [prices, Math.min(fee, 49999)];
}
